    //wire [31:0]                        mac_apb_pwdata;
    wire mac_apb_pready ; 
    wire mac_apb_pslverr ; 
    //wire                               mac_apb_penable;
    wire mac_apb_psel ; 
    wire mac_apb_pwrite ; 
    wire mac_apb_clk ; 
    // phy apb                         
    wire [15:0] phy_apb_prdata ; 
    //wire [31:0]                        phy_apb_paddr;
    //wire [31:0]                        phy_apb_pwdata;
    wire phy_apb_pready ; 
    wire phy_apb_pslverr ; 
    //wire                               phy_apb_penable;
    wire phy_apb_psel ; 
    //wire                               phy_apb_pwrite;
    wire phy_apb_clk ; 
    wire phy_apb_presetn ; 
    //wire                               mac_glb_rst_sync;
    //wire                               mac_glb_rst_sync_n;
    // 16GMII RX Interface     
    wire [15:0] gmii_16_rx_d_int ; 
    wire [1:0] gmii_16_rx_dv_int ; 
    wire [1:0] gmii_16_rx_err_int ; 
    // 16GMII TX Interface                    
    wire [15:0] gmii_16_tx_d_int ; 
    wire [1:0] gmii_16_tx_en_int ; 
    wire [1:0] gmii_16_tx_err_int ; 
    wire phy_rst_done ; 
    wire rxoutclk_ok ; 
    wire txoutclk_ok ; 
    wire phy_cdr_valid_o ; 
    //wire                               xmit_autoneg_unused;
    //assign xmit_autoneg_unused = 1'b0;
    assign phy_init_done_o = ((phy_rst_done & txoutclk_ok) & rxoutclk_ok) ; 
    // clk
    assign phy_apb_clk = sysbus_clk_i ; 
    assign mac_apb_clk = sysbus_clk_i ; 
    // reset
    assign phy_apb_presetn = reset_n_i ; 
    //------------------------------------------------------------------------------------------------------------
    // 10G MAC with Dynamic Speed selection enabled
    // Using GMII 16-bits 
    //------------------------------------------------------------------------------------------------------------
    generate
        if ((PMI_FAMILY == "LFCPNX")) 
            begin : genblk1
                if ((IP_OPTION == "MAC + PHY")) 
                    begin : genblk1
                        //wire declaration
                        wire phyrdy_o_sync ; 
                        wire xg_pcsrdy_i_l ; 
                        wire xg_rx_rst_n_i_l ; 
                        wire phyrdy_o_w ; 
                        wire rxclk_rstn_sync ; 
                        wire phy_txrdy_o_w ; 
                        wire phy_txrdy_o_sync ; 
                        wire sysbus_rstn_sync ; 
                        //------------------------------------------------------------------------------------------------------------
                        // APB address decoder for MAC and PHY
                        //
                        // 0x0000 - 0x3FFF : MAC
                        // 0x5000 – end    : PHY
                        //UCSIP-4622
                        //No APB error same as MAC and TSU implementation.
                        //Tied to low
                        assign phy_apb_pslverr = 'b0 ; 
                        assign phy_apb_psel = ((apb_paddr_i[14] & apb_paddr_i[12]) & apb_psel_i) ; 
                        assign mac_apb_psel = ((~(apb_paddr_i[14] & apb_paddr_i[12])) & apb_psel_i) ; 
                        assign apb_pready_o = ((apb_paddr_i[14] & apb_paddr_i[12]) ? phy_apb_pready : mac_apb_pready) ; 
                        assign apb_prdata_o = ((apb_paddr_i[14] & apb_paddr_i[12]) ? {16'h0,
                                    phy_apb_prdata} : mac_apb_prdata) ; 
                        assign apb_pslverr_o = ((apb_paddr_i[14] & apb_paddr_i[12]) ? phy_apb_pslverr : mac_apb_pslverr) ; 
                        assign phy_rst_done = 1'b0 ; 
                        assign txoutclk_ok = 1'b0 ; 
                        assign rxoutclk_ok = 1'b0 ; 
                        // Lint
                        assign xg_pcsrdy_i_l = (phyrdy_o_sync & phy_txrdy_o_sync) ; 
                        assign xg_rx_rst_n_i_l = ((rxclk_rstn_sync & phyrdy_o_sync) & phy_txrdy_o_sync) ; 
                        assign phyrdy_o = phyrdy_o_w ; 
                        assign phy_txrdy_o = phy_txrdy_o_w ; 
                        eth_2p5g_lane0_ipgen_lscc_reset #(.RESET_MODE("ASYNC"),
                                .SYNC_STAGE(3)) u_rxclk_rstn_sync_inst (.src_rst_n(reset_n_i), 
                                    .dest_clk(phy_rx_clk_o), 
                                    .dest_rst(), 
                                    .dest_rst_n(rxclk_rstn_sync)) ; 
                        eth_2p5g_lane0_ipgen_lscc_reset #(.RESET_MODE("ASYNC"),
                                .SYNC_STAGE(3)) u_sysbus_rstn_sync_inst (.src_rst_n(reset_n_i), 
                                    .dest_clk(phy_apb_clk), 
                                    .dest_rst(), 
                                    .dest_rst_n(sysbus_rstn_sync)) ; 
                        eth_2p5g_lane0_ipgen_lscc_sync #(.DEST_RST_MODE("SYNC"),
                                .SYNC_STAGE(3)) phyrdy_o_sync_cpnx_inst (.in_data(phyrdy_o_w), 
                                    .dest_rst_n(rxclk_rstn_sync), 
                                    .dest_clk(phy_rx_clk_o), 
                                    .out_data(phyrdy_o_sync)) ; 
                        eth_2p5g_lane0_ipgen_lscc_sync #(.DEST_RST_MODE("SYNC"),
                                .SYNC_STAGE(3)) phy_txrdy_o_sync_cpnx_inst (.in_data(phy_txrdy_o_w), 
                                    .dest_rst_n(rxclk_rstn_sync), 
                                    .dest_clk(phy_rx_clk_o), 
                                    .out_data(phy_txrdy_o_sync)) ; 
                        eth_2p5g_lane0_ipgen_lscc_ten_gbe_mac #(.IP_OPTION("MAC + PHY"),
                                .PMI_FAMILY(PMI_FAMILY),
                                .SPEED_SEL(SPEED_SEL),
                                .HOST_IF(HOST_IF),
                                .DYN_SPEED_SEL(DYN_SPEED_SEL),
                                .MC_ADDR_FILT(MC_ADDR_FILT),
                                .STATS_CNTR(STATS_CNTR),
                                .TX_STATS_CNTR(TX_STATS_CNTR),
                                .RX_STATS_CNTR(RX_STATS_CNTR),
                                .STATS_WIDTH(STATS_WIDTH),
                                .PMI_DEPTH(PMI_DEPTH),
                                .TX_PAUSE_PORTS(TX_PAUSE_PORTS)) lscc_ten_gbe_mac_inst (//UCSIP-2976
                                //UCSIP-2976
                                //UCSIP-2976
                                .reset_n_i(reset_n_i), 
                                    .rxmac_clk_i(phy_rx_clk_o),  //Connect from PHY
                                .txmac_clk_i(phy_tx_clk_o),  //Connect from PHY
                                .speed_sel_i(2'b10), 
                                    .tx_paustm_i(tx_paustm_i), 
                                    .tx_pausreq_i(tx_pausreq_i), 
                                    // xgmii interface
                                .xgmii_rxd_i(xgmii_rxd_i),  //hidden through metadata
                                .xgmii_rxc_i(xgmii_rxc_i),  //hidden through metadata
                                .xgmii_txd_o(xgmii_txd_o),  //hidden through metadata
                                .xgmii_txc_o(xgmii_txc_o),  //hidden through metadata
                                .xg_pcsrdy_i(xg_pcsrdy_i_l), 
                                    //GMII
                                .gmii_rx_d_i(gmii_rx_d_i),  //hidden through metadata
                                .gmii_rx_dv_i(gmii_rx_dv_i),  //hidden through metadata
                                .gmii_rx_err_i(gmii_rx_err_i),  //hidden through metadata
                                .gmii_tx_d_o(gmii_tx_d_o),  //hidden through metadata
                                .gmii_tx_en_o(gmii_tx_en_o),  //hidden through metadata
                                .gmii_tx_err_o(gmii_tx_err_o),  //hidden through metadata
                                .gmii_16_rx_d_i(gmii_16_rx_d_int), 
                                    .gmii_16_rx_dv_i(gmii_16_rx_dv_int), 
                                    .gmii_16_rx_err_i(gmii_16_rx_err_int), 
                                    .gmii_16_tx_d_o(gmii_16_tx_d_int), 
                                    .gmii_16_tx_en_o(gmii_16_tx_en_int), 
                                    .gmii_16_tx_err_o(gmii_16_tx_err_int), 
                                    .mii_rx_d_i(mii_rx_d_i),  //hidden through metadata
                                .mii_rx_dv_i(mii_rx_dv_i),  //hidden through metadata
                                .mii_rx_err_i(mii_rx_err_i),  //hidden through metadata
                                .mii_tx_d_o(mii_tx_d_o),  //hidden through metadata
                                .mii_tx_en_o(mii_tx_en_o),  //hidden through metadata
                                .mii_tx_err_o(mii_tx_err_o),  //hidden through metadata
                                // tx axi signald
                                .axis_tx_tdata_i(axis_tx_tdata_i), 
                                    .axis_tx_tkeep_i(axis_tx_tkeep_i), 
                                    .axis_tx_tvalid_i(axis_tx_tvalid_i), 
                                    .axis_tx_tlast_i(axis_tx_tlast_i), 
                                    .axis_tx_tready_o(axis_tx_tready_o), 
                                    .axis_tx_tuser_i(axis_tx_tuser_i), 
                                    // rx axi signald
                                .axis_rx_tdata_o(axis_rx_tdata_o), 
                                    .axis_rx_tkeep_o(axis_rx_tkeep_o), 
                                    .axis_rx_tvalid_o(axis_rx_tvalid_o), 
                                    .axis_rx_tlast_o(axis_rx_tlast_o), 
                                    .axis_rx_tuser_o(axis_rx_tuser_o), 
                                    // apb signals
                                .sysbus_clk_i(sysbus_clk_i), 
                                    .apb_psel_i(mac_apb_psel), 
                                    .apb_paddr_i(apb_paddr_i), 
                                    .apb_pwdata_i(apb_pwdata_i), 
                                    .apb_pwrite_i(apb_pwrite_i), 
                                    .apb_penable_i(apb_penable_i), 
                                    .apb_pready_o(mac_apb_pready), 
                                    .apb_pslverr_o(mac_apb_pslverr), 
                                    .apb_prdata_o(mac_apb_prdata), 
