                                .RXEQ_ALGO(RXEQ_ALGO),
                                .GEN3_ENA_PREA0(GEN3_ENA_PREA0),
                                .GEN12_ENA_PREA0(GEN12_ENA_PREA0),
                                .GEN3_ENA_POST_A0(GEN3_ENA_POST_A0),
                                .GEN12_ENA_POST_A0(GEN12_ENA_POST_A0),
