                                // serial interface
                                .pad_refclkp_i(pad_refclkp_i), 
                                    .pad_refclkn_i(pad_refclkn_i), 
                                    .refclkp0_ext_i(refclkp0_ext_i), 
                                    .refclkn0_ext_i(refclkn0_ext_i), 
                                    .refclkp1_ext_i(refclkp1_ext_i), 
                                    .refclkn1_ext_i(refclkn1_ext_i), 
                                    .pad_rxp_i(pad_rxp_i), 
                                    .pad_rxn_i(pad_rxn_i), 
                                    .pad_txp_o(pad_txp_o), 
                                    .pad_txn_o(pad_txn_o), 
                                    .pll_0_refclk_i(pll_0_refclk_i), 
                                    .pll_1_refclk_i(pll_1_refclk_i), 
                                    .sd_pll_refclk_i(sd_pll_refclk_i), 
                                    .sd_ext_0_refclk_i(sd_ext_0_refclk_i), 
                                    .sd_ext_1_refclk_i(sd_ext_1_refclk_i), 
                                    .use_refmux_i(use_refmux_i), 
                                    .diffioclksel_i(diffioclksel_i), 
                                    .clksel_i(clksel_i), 
                                    .debug_link_timer_short(debug_link_timer_short), 
                                    .force_isolate(1'b0), 
                                    .force_loopback(1'b0), 
                                    .force_unidir(1'b0), 
                                    .an_link_ok(an_link_ok), 
                                    .tx_d_16b(gmii_16_tx_d_int),  //From MAC GMII 16-bits 
                                .tx_en_2b(gmii_16_tx_en_int),  //From MAC GMII 16-bits
                                .tx_er_2b(gmii_16_tx_err_int),  //From MAC GMII 16-bits         
                                .mr_adv_ability(mr_adv_ability), 
