                                .rx_dv_2b(gmii_16_rx_dv_int),  //From MAC GMII 16-bits
                                .rx_er_2b(gmii_16_rx_err_int),  //From MAC GMII 16-bits
                                .xmit_autoneg(), 
                                    // other signals
                                .xg_tx_clk_o(phy_tx_clk_o),  //connec to TX MAC,156.25MHZ 
                                .xg_tx_clk_i(phy_tx_clk_o), 
