                                    .apb_preset_n_i(sysbus_rstn_sync), 
                                    .apb_psel_i(phy_apb_psel), 
                                    .apb_penable_i(apb_penable_i), 
                                    .apb_paddr_i(apb_paddr_i[15:0]), 
                                    .apb_pwdata_i(apb_pwdata_i[15:0]), 
                                    .apb_pwrite_i(apb_pwrite_i), 
                                    .apb_prdata_o(phy_apb_prdata), 
                                    .apb_pready_o(phy_apb_pready)) ; 
                    end
                else
                    if ((IP_OPTION == "PHY only")) 
