//                              -*- Mode: Verilog -*-
// Filename        : hotplug_ctl.v
// Description     : To handle the hotplug scenario for ethernet by controlling the rx_data_en_q0 pin.
// Author          : Lattice Semiconductor Corp
// Created On      : Mon Feb 17 10:48:51 2025
// Last Modified By: Lattice Semiconductor Corp
// Last Modified On: Mon Feb 17 10:48:51 2025
// Update Count    : 0
// Status          : Done
module eth_2p5g_lane0_ipgen_hotplug_ctl (
    input txoutclk_l0_i, 
    input pma_rx0_sigdet_lf_i, 
    output reg rx_data_en_q0_o) ;
    ////////////////////////
    //Internal Signals
    reg [6:0] pma_rx0_sigdet_lf_low_cnt = 'd0 ; 
    reg [6:0] rx_data_en_low_cnt = 'd0 ; 
    reg [12:0] rx_data_en_low_and_sigdet_lf_cnt = 'd0 ; 
    ///////////////////////////
    //For Simulation Only
    always
        @(posedge txoutclk_l0_i)
        begin
            if ((pma_rx0_sigdet_lf_i == 1'b0)) 
                begin
                    if ((pma_rx0_sigdet_lf_low_cnt != 7'h7F)) 
                        begin
                            pma_rx0_sigdet_lf_low_cnt <=  (pma_rx0_sigdet_lf_low_cnt + 7'b1) ;
                        end
                end
            else
                begin
                    pma_rx0_sigdet_lf_low_cnt <=  7'b0 ;
                end
        end
    always
        @(posedge txoutclk_l0_i)
        begin
            if ((pma_rx0_sigdet_lf_low_cnt == 7'h7F)) 
                begin
                    rx_data_en_low_cnt <=  7'h7F ;
                end
            else
                begin
                    if ((rx_data_en_low_cnt != 7'b0)) 
                        begin
                            rx_data_en_low_cnt <=  (rx_data_en_low_cnt - 7'h1) ;
                        end
                end
        end
    always
        @(posedge txoutclk_l0_i)
        begin
            if ((pma_rx0_sigdet_lf_low_cnt == 7'h7F)) 
                begin
                    rx_data_en_low_and_sigdet_lf_cnt <=  13'h0 ;
                end
            else
                begin
                    if (((rx_data_en_q0_o == 1'b0) && (pma_rx0_sigdet_lf_i == 1'b1))) 
                        begin
                            if ((rx_data_en_low_and_sigdet_lf_cnt != 13'h1FFF)) 
                                begin
                                    rx_data_en_low_and_sigdet_lf_cnt <=  (rx_data_en_low_and_sigdet_lf_cnt + 12'h1) ;
                                end
                        end
                end
        end
    always
        @(posedge txoutclk_l0_i)
        begin
            if ((pma_rx0_sigdet_lf_low_cnt == 7'h7F)) 
                begin
                    rx_data_en_q0_o <=  1'b0 ;
                end
            else
                if (((((rx_data_en_low_cnt == 7'd0) && (rx_data_en_low_and_sigdet_lf_cnt == 13'h1FFF)) && (rx_data_en_q0_o == 1'b0)) && (pma_rx0_sigdet_lf_i == 1'b1))) 
                    begin
                        rx_data_en_q0_o <=  1'b1 ;
                    end
        end

// hotplug_ctl
endmodule




