`timescale 1ns/1ps
module eth_2p5g_lane0_ipgen_mpp_rx_remap (
    input clk, 
    input rst_n, 
    input [159:0] pma_rx_data_i, 
    input [3:0] rx_am_i, 
    output [159:0] pma_rx_data_o, 
    output [3:0] rx_am_o) ;
    reg [79:0] pma_rx_data_r ; 
    reg rx_am_r ; 
    always
        @(posedge clk or 
            negedge rst_n)
        begin
            if ((~rst_n)) 
                begin
                    pma_rx_data_r <=  80'b0 ;
                    rx_am_r <=  1'b0 ;
                end
            else
                begin
                    pma_rx_data_r <=  pma_rx_data_i[159:80] ;
                    rx_am_r <=  rx_am_i[1] ;
                end
        end
    assign pma_rx_data_o = {pma_rx_data_i[79:0],
                pma_rx_data_r} ; 
    assign rx_am_o = {rx_am_i[3:2],
                rx_am_i[0],
                rx_am_r} ; 
endmodule



