                .rx_valid_q1_o()) ; 
endmodule



`timescale 1ns/1ps
module eth_2p5g_lane0_ipgen_mppcs_enc_rd_calc (
    input cr_tx_dbus_20b,  //0=10b-data; 1=20b-data
    input clk, 
    input rstn, 
    input din_val, 
    input [1:0] din_frcdisp, 
    input [1:0] din_dispval, 
    input [19:0] din_8b, 
    output reg dout_val, 
    output reg [1:0] dout_frcdisp, 
    output reg [1:0] dout_dispval, 
    output reg [19:0] dout_8b) ;
    reg curr_rd ; 
    wire [1:0] rd ; 
    wire [1:0] rd_flip ; 
    wire [1:0] cordisp ; 
    assign cordisp[1] = din_8b[19] ; 
    assign cordisp[0] = din_8b[9] ; 
    eth_2p5g_lane0_ipgen_mppcs_enc_rd_calc_byte rd_calc_byte0 (.curr_rd(curr_rd), 
                .din_8b(din_8b[9:0]), 
                .rd_flip(rd_flip[0])) ; 
    eth_2p5g_lane0_ipgen_mppcs_enc_rd_calc_byte rd_calc_byte1 (.curr_rd(rd[0]), 
                .din_8b(din_8b[19:10]), 
                .rd_flip(rd_flip[1])) ; 
    //current RD from force disparity value
    //invert current RD from last code group disparity
    assign rd[0] = (din_frcdisp[0] ? (rd_flip[0] ? (~din_dispval[0]) : din_dispval[0]) : (din_dispval[0] ? (rd_flip[0] ? curr_rd : (~curr_rd)) : (rd_flip[0] ? (~curr_rd) : curr_rd))) ; //current RD from last code group disparity
    //current RD from force disparity value
    //invert current RD from last code group disparity
    assign rd[1] = (din_frcdisp[1] ? (rd_flip[1] ? (~din_dispval[1]) : din_dispval[1]) : (din_dispval[1] ? (rd_flip[1] ? rd[0] : (~rd[0])) : (rd_flip[1] ? (~rd[0]) : rd[0]))) ; //current RD from last code group disparity
    always
        @(posedge clk or 
            negedge rstn)
        begin
            if ((~rstn)) 
                begin
                    curr_rd <=  1'b0 ;//curr_rd start for -ve
                end
            else
                begin
                    if (din_val) 
                        begin
                            if (cr_tx_dbus_20b) 
                                begin
                                    curr_rd <=  rd[1] ;
                                end
                            else
                                begin
                                    curr_rd <=  rd[0] ;
                                end
                        end
                end
        end
    always
        @(posedge clk or 
            negedge rstn)
        begin
            if ((~rstn)) 
                begin
                    dout_val <=  1'b0 ;
                    dout_frcdisp <=  2'b0 ;
                    dout_dispval <=  2'b0 ;
                    dout_8b <=  10'b0 ;
                end
            else
                begin
                    dout_val <=  din_val ;
                    dout_frcdisp <=  din_frcdisp ;
                    dout_dispval <=  din_dispval ;
                    dout_8b[19] <=  1'b0 ;//always drive 0 to cordisp into HIP  
                    dout_8b[9] <=  1'b0 ;//always drive 0 to cordisp into HIP  
                    dout_8b[18:10] <=  (((~rd[0]) & cordisp[1]) ? 9'hC5 : din_8b[18:10]) ;//when curr_rd is -ve, means EOP of frame is +ve and need to replace 'h50 with 'hc5   
                    dout_8b[8:0] <=  (((~curr_rd) & cordisp[0]) ? 9'hC5 : din_8b[8:0]) ;//when curr_rd is -ve, means EOP of frame is +ve and need to replace 'h50 with 'hc5 
                end
        end
endmodule



`timescale 1ns/1ps
module eth_2p5g_lane0_ipgen_mppcs_enc_rd_calc_byte (
    input curr_rd, 
    input [9:0] din_8b, 
    output rd_flip) ;
    wire k ; 
    wire [4:0] d5 ; 
    wire [2:0] d3 ; 
    reg rd_flip_5 ; 
    reg rd_flip_3 ; 
    reg rd_flip_k ; 
    wire cordisp ; 
    assign cordisp = din_8b[9] ; 
    assign d3 = din_8b[7:5] ; 
    assign d5 = din_8b[4:0] ; 
    assign k = din_8b[8] ; 
    always
        @(*)
        begin
            case ({k,
                    d5})
            6'b000000 : 
                //data
                rd_flip_5 = 1'b1 ;
            6'b000001 : 
                rd_flip_5 = 1'b1 ;
            6'b000010 : 
                rd_flip_5 = 1'b1 ;
            6'b000100 : 
                rd_flip_5 = 1'b1 ;
            6'b001000 : 
                rd_flip_5 = 1'b1 ;
            6'b001111 : 
                rd_flip_5 = 1'b1 ;
            6'b010000 : 
                rd_flip_5 = 1'b1 ;
            6'b010111 : 
                rd_flip_5 = 1'b1 ;
            6'b011000 : 
                rd_flip_5 = 1'b1 ;
            6'b011011 : 
                rd_flip_5 = 1'b1 ;
            6'b011101 : 
                rd_flip_5 = 1'b1 ;
            6'b011110 : 
                rd_flip_5 = 1'b1 ;
            6'b011111 : 
                rd_flip_5 = 1'b1 ;
            default : 
                rd_flip_5 = 1'b0 ;
            endcase 
        end
    always
        @(*)
        begin
            case ({k,
                    d3})
            4'b0001 : 
                //data
                rd_flip_3 = 1'b1 ;
            4'b0010 : 
                rd_flip_3 = 1'b1 ;
            4'b0011 : 
                rd_flip_3 = 1'b1 ;
            4'b0101 : 
                rd_flip_3 = 1'b1 ;
            4'b0110 : 
                rd_flip_3 = 1'b1 ;
            default : 
                rd_flip_3 = 1'b0 ;
            endcase 
        end
    always
        @(*)
        begin
            case ({k,
                    d3,
                    d5})
            9'b1_001_11100 : 
                //control
                rd_flip_k = 1'b1 ;
            9'b1_010_11100 : 
                rd_flip_k = 1'b1 ;
            9'b1_011_11100 : 
                rd_flip_k = 1'b1 ;
            9'b1_101_11100 : 
                rd_flip_k = 1'b1 ;
            9'b1_110_11100 : 
                rd_flip_k = 1'b1 ;
            default : 
                rd_flip_k = 1'b0 ;
            endcase 
        end
    //when curr_rd is -ve, means EOP of frame is +ve and need to replace 'h50 with 'hc5 which is neutral
    assign rd_flip = (((~curr_rd) & cordisp) ? 1'b0 : (k ? rd_flip_k : (~(rd_flip_5 ^ rd_flip_3)))) ; 
endmodule


